//! The native agent must agree byte for byte with agent/policy.py.
//! Vectors are generated by tools/gen_policy_vectors.py.

use openems_agent::canonical::canonical_json;
use openems_agent::policy::{
    WebRules, normalize_domain, normalize_domain_rule, normalize_process, policy_digest, validate_policy,
};
use serde_json::Value;

fn vectors() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../contract/policy-vectors.json");
    let text = std::fs::read_to_string(path).expect("shared policy vectors are readable");
    serde_json::from_str(&text).expect("shared policy vectors are valid JSON")
}

fn cases<'a>(vectors: &'a Value, section: &str) -> &'a Vec<Value> {
    vectors[section].as_array().expect("vector section is a list")
}

#[test]
fn canonical_encoding_and_digest_match_python() {
    let vectors = vectors();
    for case in cases(&vectors, "policies") {
        let body = case["body"].as_object().expect("policy body is an object");
        assert_eq!(canonical_json(&case["body"]), case["canonical"].as_str().unwrap(), "canonical form of {body:?}");
        assert_eq!(policy_digest(body), case["digest"].as_str().unwrap(), "digest of {body:?}");
    }
}

#[test]
fn domain_normalization_matches_python() {
    let vectors = vectors();
    for case in cases(&vectors, "domains") {
        let input = case["input"].as_str().unwrap();
        match case.get("normalized") {
            Some(expected) => {
                assert_eq!(normalize_domain(input).as_deref().ok(), expected.as_str(), "domain {input:?}")
            }
            None => assert!(normalize_domain(input).is_err(), "domain {input:?} must be rejected"),
        }
    }
}

#[test]
fn process_normalization_matches_python() {
    let vectors = vectors();
    for case in cases(&vectors, "processes") {
        let input = case["input"].as_str().unwrap();
        match case.get("normalized") {
            Some(expected) => {
                assert_eq!(normalize_process(input).as_deref().ok(), expected.as_str(), "process {input:?}")
            }
            None => assert!(normalize_process(input).is_err(), "process {input:?} must be rejected"),
        }
    }
}

#[test]
fn policy_validation_matches_python() {
    let vectors = vectors();
    for case in cases(&vectors, "validate") {
        let result = validate_policy(&case["input"]);
        match case.get("normalized") {
            Some(expected) => assert_eq!(result.ok().as_ref(), Some(expected), "policy {}", case["input"]),
            None => assert!(result.is_err(), "policy {} must be rejected", case["input"]),
        }
    }
}

#[test]
fn oversized_lists_are_rejected() {
    let blocked: Vec<Value> = (0..10_001).map(|index| Value::String(format!("site{index}.example.com"))).collect();
    let body = serde_json::json!({ "web_filter": { "blocked": blocked } });
    assert!(validate_policy(&body).is_err());
}

fn strings(value: &Value) -> Vec<String> {
    value.as_array().unwrap().iter().map(|item| item.as_str().unwrap().to_owned()).collect()
}

#[test]
fn domain_rule_normalization_matches_python() {
    let vectors = vectors();
    for case in cases(&vectors, "domain_rules") {
        let input = case["input"].as_str().unwrap();
        match case.get("normalized") {
            Some(expected) => {
                assert_eq!(normalize_domain_rule(input).as_deref().ok(), expected.as_str(), "rule {input:?}")
            }
            None => assert!(normalize_domain_rule(input).is_err(), "rule {input:?} must be rejected"),
        }
    }
}

#[test]
fn rule_matching_matches_python() {
    let vectors = vectors();
    for case in cases(&vectors, "matches") {
        let rules = WebRules::new(&strings(&case["blocked"]), &strings(&case["allowed"])).unwrap();
        let name = case["name"].as_str().unwrap();
        assert_eq!(rules.blocks(name), case["result"].as_bool().unwrap(), "match {case}");
    }
}

#[test]
fn hosts_expansion_matches_python() {
    let vectors = vectors();
    for case in cases(&vectors, "hosts_names") {
        let rules = WebRules::new(&strings(&case["blocked"]), &strings(&case["allowed"])).unwrap();
        assert_eq!(rules.hosts_names(), strings(&case["names"]), "hosts {case}");
    }
}

#[test]
fn oversized_allow_lists_are_rejected() {
    let allowed: Vec<Value> = (0..10_001).map(|index| Value::String(format!("site{index}.example.com"))).collect();
    let body = serde_json::json!({ "web_filter": { "allowed": allowed } });
    assert!(validate_policy(&body).is_err());
}
